```go
package main

import (
	"fmt"
	"net/http"

	"golang.org/x/time/rate"

	"yourproject/middleware"
)

func handler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "Hello, world!")
}

func main() {
	rl := middleware.NewRateLimiter(rate.Limit(10), 20)

	http.Handle("/", rl.Middleware(http.HandlerFunc(handler)))
	http.ListenAndServe(":8080", nil)
}
```

This middleware limits each client IP to 10 requests per second with a maximum burst of 20. When exceeded, it returns 429 with a `Retry-After: 1` header. The limiter map is protected by a mutex for concurrency safety.

