func startWorkerPool(numWorkers int, jobs chan int, results chan int) *sync.WaitGroup {
	var wg sync.WaitGroup
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go worker(i, jobs, results, &wg)
	}
	return &wg
}

package main

