import time
import functools
import requests
from typing import Callable, TypeVar, Any

T = TypeVar('T')

def retry_with_backoff(func: Callable[..., T]) -> Callable[..., T]:
    """Retry a function with exponential backoff on RequestException.

    Retries up to 4 total attempts (initial + 3 retries).
    Backoff starts at 0.5 seconds and doubles each retry.
    Re-raises non-RequestException immediately and last exception after retries.
    """
    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> T:
        delay = 0.5
        last_exception = None
        for attempt in range(4):
            try:
                return func(*args, **kwargs)
            except requests.exceptions.RequestException as e:
                last_exception = e
                if attempt < 3:
                    time.sleep(delay)
                    delay *= 2
        raise last_exception  # type: ignore[return-value]
    return wrapper
EOF
