def load_config_with_defaults(defaults):
    import json
    try:
        with open('./config/app_settings.json', 'r') as f:
            file_config = json.load(f)
        # Merge with defaults (file config overrides defaults)
        merged = {**defaults, **file_config}
        # Handle nested dictionaries
        for key in merged:
            if key in defaults and isinstance(defaults[key], dict) and isinstance(merged[key], dict):
                merged[key] = {**defaults[key], **merged[key]}
