{"file_path": "src/services/payments.js", "content": "const { randomUUID } = require('crypto');
const logger = require('./logger');

async function fetchWithError(url, options = {}) {
  try {
    const res = await fetch(url, options);
    if (!res.ok) {
      const text = await res.text();
      throw new Error(`HTTP ${res.status}: ${res.statusText} - ${text}`);
    }
    return res.json();
  } catch (e) {
    throw new Error(`Network error: ${e.message}`, { cause: e });
  }
}

async function fetchUser(userId) {
  return fetchWithError(`/users/${userId}`);
}

async function fetchAccount(userId) {
  return fetchWithError(`/accounts/${userId}`);
}

async function chargeAccount(accountId, amount) {
  return fetchWithError(`/charge`, { method: 'POST', body: JSON.stringify({ accountId, amount }) });
}

async function processPayment(userId, amount) {
  const correlationId = randomUUID();
  try {
    let user, account, result;
    try {
      user = await fetchUser(userId);
    } catch (e) {
      const msg = 'Failed to fetch user';
      logger.error(msg, { correlationId, error: e.message });
      throw new Error(msg, { cause: e });
    }
    try {
      account = await fetchAccount(user.id);
    } catch (e) {
      const msg = 'Failed to fetch account';
      logger.error(msg, { correlationId, error: e.message });
      throw new Error(msg, { cause: e });
    }
    try {
      result = await chargeAccount(account.id, amount);
    } catch (e) {
      const msg = 'Failed to charge account';
      logger.error(msg, { correlationId, error: e.message });
      throw new Error(msg, { cause: e });
    }
    return result;
  } catch (e) {
    return { success: false, error: e.message };
  }
}

module.exports = { processPayment };
"}

