def handle_order_status(payload: dict) -> dict:
    # Validate required fields
    if 'order_id' not in payload or 'status' not in payload:
        return {'error': 'Invalid payload: missing order_id or status'}
    order_id = payload['order_id']
    status = payload['status']
    # Validate order_id format
    if not re.match(r'^ORD-\d{5}$', order_id):
        return {'error': f'Invalid payload: order_id {order_id!r} does not match pattern ^ORD-\d{5}$'}
    # Validate status
    valid_statuses = ['pending', 'shipped', 'delivered', 'cancelled']
    if status not in valid_statuses:
        return {'error': f'Invalid payload: status {status!r} is not one of {valid_statuses}'}
    return {'result': 'acknowledged', 'order_id': order_id, 'status': status}

if __name__ == '__main__':
    sample = {'order_id': 'ORD-12345', 'status': 'shipped', 'timestamp': '2025-03-15T10:30:00Z'}
